export const DAILY_UI_META={"schema":1,"task":"T34","agent":"daily_pet_ui_art","coordinateConvention":"All rect arrays are [x,y,width,height] in original atlas pixels. clipPolygon and foot are LOCAL to rect. safeRect is LOCAL to rect. Do not equal-split this atlas.","images":{"daily":{"file":"daily-ui-v2.png","size":[1536,1024],"sprites":{"rail":{"rect":[6,0,1524,160],"safeRect":[204,66,1110,28],"notes":"Long transparent interior is the progress fill slot. Chests are separate assets. Keep rail original aspect ratio."},"taskRow":{"rect":[45,188,1185,182],"safeRect":[159,57,874,68],"notes":"Live task description and claim control go inside this conservative clear area."},"dailyBadge":{"rect":[1252,158,244,237],"clipPolygon":[[0,0],[244,0],[244,237],[82,237],[82,210],[0,210]],"notes":"Six-vertex clip excludes neighbour chest crest from the bottom-left of the badge crop.","cssClipPath":"polygon(0.0% 0.0%,100.0% 0.0%,100.0% 100.0%,33.6066% 100.0%,33.6066% 88.6076%,0.0% 88.6076%)"},"chestSmallClosed":{"rect":[117,424,277,218],"foot":[138,211],"family":"small","state":"closed"},"chestMediumClosed":{"rect":[591,405,312,236],"foot":[156,228],"family":"medium","state":"closed"},"chestLargeClosed":{"rect":[1076,370,376,272],"foot":[188,264],"family":"large","state":"closed","clipPolygon":[[0,0],[258,0],[258,25],[376,25],[376,272],[0,272]],"notes":"Six-vertex clip excludes badge bottom tip in the crop upper-right. Chest crest remains whole.","cssClipPath":"polygon(0.0% 0.0%,68.617% 0.0%,68.617% 9.1912%,100.0% 9.1912%,100.0% 100.0%,0.0% 100.0%)"},"chestSmallOpen":{"rect":[112,698,292,289],"foot":[145.5,282],"family":"small","state":"open"},"chestMediumOpen":{"rect":[584,671,327,315],"foot":[162.5,308],"family":"medium","state":"open"},"chestLargeOpen":{"rect":[1066,643,394,348],"foot":[197,340],"family":"large","state":"open"}},"chestRendering":{"commonReference":[394,348],"instruction":"For closed/open state swaps retain one common atlas-pixel scale and align foot to the same node. Do not independently object-fit each state to its own rectangle: open lids should rise, not shrink the chest body."},"sha256":"8d5022c5d59989ee057f2609514ddfef8a6d99f4012f3181b25a58f9d258ad1d","bytes":2425266,"mode":"RGBA"},"petXp":{"file":"pet-xp-potions-v1.png","size":[1536,1024],"sprites":{"petXpSmall":{"rect":[102,482,226,374],"foot":[113,365],"tier":"small","description":"Simple jade-green spirit elixir, cork cap and gold clawprint seal."},"petXpMedium":{"rect":[470,260,408,602],"foot":[204,593],"tier":"medium","description":"Rounded emerald flask with antler filigree and claw seal."},"petXpLarge":{"rect":[1005,71,462,803],"foot":[231,794],"tier":"large","description":"Tall guardian-beast gold and teal crystal flask."}},"sha256":"fb2bc157519c337dfedf3ab8f086900a1200e1305c5511b08df9900d4935906f","bytes":1875040,"mode":"RGBA"}},"validation":{"sourcePNGsUnmodified":true,"alphaRange":[0,254],"dailyTransparentPixels":871403,"petTransparentPixels":1126532,"artViewed":true,"referenceFilenameCorrection":"Pause reference file is pause-controls-v1.png, not controls-v1.png.","remainingIssues":["The badge and large-closed chest bounding rectangles intersect in a small region; their painted silhouettes are disjoint. Apply the provided clipPolygon values when drawing these two sprites."],"dailyFrameInteriorSampling":{"rail":{"atlasRect":[210,66,1110,28],"alphaRange":[0,2],"meanAlpha":0.09678249678249679},"taskRow":{"atlasRect":[204,245,874,68],"alphaRange":[0,1],"meanAlpha":0.017616772109301387},"note":"Final conservative live-content rectangles contain no opacity above 2/255. Empty pixels may retain brown RGB beneath alpha zero; do not treat RGB preview background as opaque."},"supersededDraft":"daily-ui-v1.png retained, final active daily asset is daily-ui-v2.png"}};
const daily=DAILY_UI_META.images.daily,pet=DAILY_UI_META.images.petXp;
function cropped(sheet,rect){const [x,y,w,h]=rect,[iw,ih]=sheet.size;return `background-image:url('assets/daily-ui/${sheet.file}');background-size:${iw/w*100}% ${ih/h*100}%;background-position:${x/Math.max(1,iw-w)*100}% ${y/Math.max(1,ih-h)*100}%;`;}
const chestKeys=['Small','Medium','Large'];
export function dailyArtStyle(key){
 const match=/^chest([0-2])(Open|Closed)$/.exec(key);if(match){const f=daily.sprites['chest'+chestKeys[+match[1]]+match[2]],[x,y,w,h]=f.rect,[iw,ih]=daily.size,[rw,rh]=daily.chestRendering.commonReference,[fx,fy]=f.foot,tx=rw/2,ty=340,dx=tx-fx,dy=ty-fy,poly=f.clipPolygon||[[0,0],[w,0],[w,h],[0,h]];return `background-image:url('assets/daily-ui/${daily.file}');background-size:${iw/rw*100}% ${ih/rh*100}%;background-position:${((tx-x-fx)/(rw-iw))*100}% ${((ty-y-fy)/(rh-ih))*100}%;clip-path:polygon(${poly.map(([px,py])=>`${(dx+px)/rw*100}% ${(dy+py)/rh*100}%`).join(',')});`;}
 const f=daily.sprites[key==='entry'?'dailyBadge':key==='track'?'rail':'taskRow'];return cropped(daily,f.rect)+(f.cssClipPath?`clip-path:${f.cssClipPath};`:'');
}
export function dailyTaskFrame(){const [x,y,w,h]=daily.sprites.taskRow.rect,edge=150;return `<i class="daily-task-skin" aria-hidden="true"><span class="left" style="${cropped(daily,[x,y,edge,h])}"></span><span class="middle" style="${cropped(daily,[x+edge,y,w-edge*2,h])}"></span><span class="right" style="${cropped(daily,[x+w-edge,y,edge,h])}"></span></i>`;}
export function petPotionStyle(index){const f=Object.values(pet.sprites)[index];if(!f)return '';const [x,y,w,h]=f.rect,[iw,ih]=pet.size,side=Math.max(w,h);return `background-image:url('assets/daily-ui/${pet.file}');background-size:${iw/side*100}% ${ih/side*100}%;background-position:${(.5-(x+w/2)/side)/(1-iw/side)*100}% ${(.5-(y+h/2)/side)/(1-ih/side)*100}%;clip-path:inset(${(1-h/side)*50}% ${(1-w/side)*50}%);`;}
export const dailyProgressFill=count=>[0,20,55,100][Math.max(0,Math.min(3,count))];
export function dailyNodeLeft(index){const f=daily.sprites.rail,[x,,w]=f.safeRect;return (x+w*([.2,.55,1][index]))/f.rect[2]*100;}
